//! Runs the native source-complete mask-zero policy against checked-in vectors
//! generated by executing canonical `chooseFactoryAiMaskZeroDecision` (plus
//! one explicitly documented typed-only empty-list guard). Regenerate with
//! `node core-rs/tools/gen-factory-ai-decision-policy-vectors.mjs`.

use factory_core::factory_ai_check_bad_move::BattleRngState;
use factory_core::factory_ai_decision_policy::{
    choose_factory_ai_mask_zero_decision, FactoryAiDecisionSide, FactoryAiLegalDecision,
    FactoryAiMaskZeroDecisionInput, FactoryAiMoveDecision, FactoryAiMovePolicyRequest,
    FactoryAiMovePolicyView, FactoryAiMoveSlot, FactoryAiRequestKind, FactoryAiRngDraw,
};
use factory_core::factory_ai_decision_policy_vectors_gen::{
    FactoryAiMaskZeroErrorCase, FactoryAiMaskZeroSuccessCase, PolicyDrawRow,
    PolicyLegalDecisionRow, FACTORY_AI_MASK_ZERO_ERROR_CASES, FACTORY_AI_MASK_ZERO_SUCCESS_CASES,
};
use factory_core::factory_ai_mask::FactoryAiMaskSelectionInput;

fn slot(value: u8) -> FactoryAiMoveSlot {
    FactoryAiMoveSlot::from_index(value as usize)
        .unwrap_or_else(|| panic!("vector contains invalid move slot {value}"))
}

fn side(value: u8) -> FactoryAiDecisionSide {
    match value {
        0 => FactoryAiDecisionSide::Player,
        1 => FactoryAiDecisionSide::Trainer,
        _ => panic!("vector contains invalid side {value}"),
    }
}

fn request_kind(value: u8) -> FactoryAiRequestKind {
    match value {
        0 => FactoryAiRequestKind::Command,
        1 => FactoryAiRequestKind::ForcedSwitch,
        _ => panic!("vector contains invalid request kind {value}"),
    }
}

fn legal_decisions(rows: &[PolicyLegalDecisionRow], count: u8) -> Vec<FactoryAiLegalDecision> {
    rows[..count as usize]
        .iter()
        .map(|row| match row.kind {
            0 => FactoryAiLegalDecision::UseMove(FactoryAiMoveDecision {
                move_slot: slot(row.move_slot),
                target_battler: row.target_battler,
            }),
            1 => FactoryAiLegalDecision::Switch { party_index: row.target_battler },
            _ => panic!("vector contains invalid legal-decision kind {}", row.kind),
        })
        .collect()
}

fn view(
    level_mode: u8,
    battle_mode: u8,
    factory_win_streak: u32,
    trainer_opponent_id: u32,
    moves: [u16; 4],
) -> FactoryAiMovePolicyView {
    FactoryAiMovePolicyView {
        factory: FactoryAiMaskSelectionInput {
            level_mode,
            battle_mode,
            factory_win_streak,
            trainer_opponent_id,
        },
        moves,
    }
}

fn input_from_success<'a>(
    c: &FactoryAiMaskZeroSuccessCase,
    legal: &'a [FactoryAiLegalDecision],
) -> FactoryAiMaskZeroDecisionInput<'a> {
    FactoryAiMaskZeroDecisionInput {
        view: view(
            c.level_mode,
            c.battle_mode,
            c.factory_win_streak,
            c.trainer_opponent_id,
            c.moves,
        ),
        request: FactoryAiMovePolicyRequest {
            kind: request_kind(c.request_kind),
            request_id: c.request_id,
            side: side(c.side),
            battler: c.battler,
            legal_decisions: legal,
        },
        rng: BattleRngState { value: c.rng_value, calls: c.rng_calls },
    }
}

fn input_from_error<'a>(
    c: &FactoryAiMaskZeroErrorCase,
    legal: &'a [FactoryAiLegalDecision],
) -> FactoryAiMaskZeroDecisionInput<'a> {
    FactoryAiMaskZeroDecisionInput {
        view: view(
            c.level_mode,
            c.battle_mode,
            c.factory_win_streak,
            c.trainer_opponent_id,
            c.moves,
        ),
        request: FactoryAiMovePolicyRequest {
            kind: request_kind(c.request_kind),
            request_id: c.request_id,
            side: side(c.side),
            battler: c.battler,
            legal_decisions: legal,
        },
        rng: BattleRngState { value: c.rng_value, calls: c.rng_calls },
    }
}

fn assert_draw(
    actual: FactoryAiRngDraw,
    expected: PolicyDrawRow,
    case_index: usize,
    draw_index: usize,
) {
    match (actual, expected.kind) {
        (FactoryAiRngDraw::SetupSimulatedRng(draw), 0) => {
            assert_eq!(
                draw.move_slot as u8, expected.move_slot,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.simulated_rng, expected.simulated_rng,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.ordinal, expected.ordinal,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.before.value, expected.before_value,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.before.calls, expected.before_calls,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.after.value, expected.after_value,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.after.calls, expected.after_calls,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.raw_rng_value, expected.raw_rng_value,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.random_value, expected.random_value,
                "case {case_index} draw {draw_index}"
            );
        }
        (FactoryAiRngDraw::BestMoveTie(draw), 1) => {
            assert_eq!(
                expected.move_slot, 255,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.ordinal, expected.ordinal,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.before.value, expected.before_value,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.before.calls, expected.before_calls,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.after.value, expected.after_value,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.after.calls, expected.after_calls,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.raw_rng_value, expected.raw_rng_value,
                "case {case_index} draw {draw_index}"
            );
            assert_eq!(
                draw.random_value, expected.random_value,
                "case {case_index} draw {draw_index}"
            );
        }
        (actual, expected_kind) => panic!(
            "case {case_index} draw {draw_index}: expected kind {expected_kind}, got {actual:?}"
        ),
    }
}

#[test]
fn success_cases_match_canonical_typescript_policy() {
    assert!(!FACTORY_AI_MASK_ZERO_SUCCESS_CASES.is_empty());
    for (case_index, c) in FACTORY_AI_MASK_ZERO_SUCCESS_CASES.iter().enumerate() {
        let legal = legal_decisions(&c.legal, c.legal_count);
        let result = choose_factory_ai_mask_zero_decision(input_from_success(c, &legal))
            .unwrap_or_else(|error| {
                panic!("case {case_index}: {c:?} unexpectedly errored: {error}")
            });

        assert_eq!(
            result.rng.value, c.expected_rng_value,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.rng.calls, c.expected_rng_calls,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.trace.mask, c.expected_mask,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.trace.mask_selection.mask, c.expected_mask,
            "case {case_index}: {c:?}"
        );
        let receipt = result.trace.mask_selection.receipt;
        assert_eq!(
            receipt.branch as u8, c.expected_branch,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            receipt.is_frontier_brain, c.expected_is_frontier_brain,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            receipt.challenge_number.is_some(),
            c.expected_has_challenge_number,
            "case {case_index}: {c:?}"
        );
        if c.expected_has_challenge_number {
            assert_eq!(
                receipt.challenge_number,
                Some(c.expected_challenge_number),
                "case {case_index}: {c:?}"
            );
        }
        assert_eq!(
            receipt.evaluation_count, c.expected_evaluation_count,
            "case {case_index}: {c:?}"
        );
        for (evaluation_index, expected) in c
            .expected_evaluations
            .iter()
            .take(c.expected_evaluation_count as usize)
            .enumerate()
        {
            let actual = receipt.evaluations[evaluation_index];
            assert_eq!(
                actual.branch as u8, expected.branch,
                "case {case_index} evaluation {evaluation_index}"
            );
            assert_eq!(
                actual.matched, expected.matched,
                "case {case_index} evaluation {evaluation_index}"
            );
        }

        for (draw_index, (&actual, &expected)) in result
            .trace
            .draws
            .iter()
            .zip(c.expected_draws.iter())
            .enumerate()
        {
            assert_draw(actual, expected, case_index, draw_index);
        }
        for (slot_index, (&actual, &expected)) in result
            .trace
            .slot_scores
            .iter()
            .zip(c.expected_slots.iter())
            .enumerate()
        {
            assert_eq!(
                actual.move_slot as u8, expected.move_slot,
                "case {case_index} slot {slot_index}"
            );
            assert_eq!(
                actual.move_id, expected.move_id,
                "case {case_index} slot {slot_index}"
            );
            assert_eq!(
                actual.legal, expected.legal,
                "case {case_index} slot {slot_index}"
            );
            assert_eq!(
                actual.initial_score, expected.initial_score,
                "case {case_index} slot {slot_index}"
            );
            assert_eq!(
                actual.final_score, expected.final_score,
                "case {case_index} slot {slot_index}"
            );
        }
        let best_count = c.expected_best_slot_count as usize;
        assert_eq!(
            result.trace.best_move_slots[..best_count]
                .iter()
                .map(|slot| *slot as u8)
                .collect::<Vec<_>>(),
            c.expected_best_slots[..best_count],
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.trace.best_move_slot_count, c.expected_best_slot_count,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.trace.tie_modulus, c.expected_tie_modulus,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.trace.tie_index, c.expected_tie_index,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.trace.chosen_decision.move_slot as u8, c.expected_chosen_slot,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.trace.chosen_decision.target_battler, c.expected_chosen_target,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.submission.request_id, c.expected_submission_request_id,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.submission.side as u8, c.expected_submission_side,
            "case {case_index}: {c:?}"
        );
        assert_eq!(
            result.submission.decision, result.trace.chosen_decision,
            "case {case_index}: {c:?}"
        );
    }
}

#[test]
fn typed_reachable_errors_match_exact_policy_messages() {
    assert!(!FACTORY_AI_MASK_ZERO_ERROR_CASES.is_empty());
    for (case_index, c) in FACTORY_AI_MASK_ZERO_ERROR_CASES.iter().enumerate() {
        let legal = legal_decisions(&c.legal, c.legal_count);
        let error = match choose_factory_ai_mask_zero_decision(input_from_error(c, &legal)) {
            Ok(result) => panic!("case {case_index}: {c:?} unexpectedly succeeded: {result:?}"),
            Err(error) => error,
        };
        assert_eq!(
            error.to_string(),
            c.expected_message,
            "case {case_index}: {c:?}"
        );
    }
}
